import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as r,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse('{"title":"GitHub API limits","description":"","frontmatter":{},"headers":[],"relativePath":"reference/github-api-limits.md","filePath":"reference/github-api-limits.md"}'),o={name:"reference/github-api-limits.md"};function s(d,e,c,n,h,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="github-api-limits" tabindex="-1">GitHub API limits <a class="header-anchor" href="#github-api-limits" aria-label="Permalink to &quot;GitHub API limits&quot;">​</a></h1><p>This page documents the hard limits of the GitHub Code Search API that affect <code>github-code-search</code>. Understanding them helps you craft effective queries and plan your usage.</p><h2 id="result-limits" tabindex="-1">Result limits <a class="header-anchor" href="#result-limits" aria-label="Permalink to &quot;Result limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Max results</strong></td><td>1,000 items</td><td>Hard cap — GitHub returns at most 10 pages × 100 items/page for code search</td></tr><tr><td><strong>Max pagination</strong></td><td>Page 10</td><td>GitHub hard cap for the code search endpoint</td></tr><tr><td><strong>Max query length</strong></td><td>256 characters</td><td>Queries exceeding this length are rejected by the API</td></tr><tr><td><strong>Fork repositories</strong></td><td>Excluded by default</td><td>Add <code>fork:true</code> to the query string to include forks</td></tr><tr><td><strong>Min query length</strong></td><td>≥ 1 non-qualifier term</td><td>A query consisting only of qualifiers (e.g. <code>language:TypeScript</code>) is rejected</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Stay under 1,000 results</p><p>If your query matches more than 1,000 files, <code>github-code-search</code> will only see the first 1,000. Use qualifiers (<code>language:</code>, <code>path:</code>, <code>filename:</code>) to narrow the results. See <a href="/github-code-search/v2/usage/search-syntax.html">Search syntax</a> for examples.</p></div><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Limit</th></tr></thead><tbody><tr><td>Unauthenticated requests</td><td>10 requests/minute</td></tr><tr><td>Authenticated (with <code>GITHUB_TOKEN</code>)</td><td>30 requests/minute</td></tr></tbody></table><p><code>github-code-search</code> always authenticates with <code>GITHUB_TOKEN</code>. Each paginated search call consumes one request. A query returning 1,000 results requires 10 requests (10 pages × 100 items).</p><div class="warning custom-block"><p class="custom-block-title">Rate limit exceeded</p><p>If the 30 req/min limit is reached, <code>github-code-search</code> surfaces a <code>GitHub API error 403</code> or <code>429</code>. Retry after the reset time indicated in the error output, or break the query into multiple narrower searches.</p></div><h2 id="query-syntax-constraints" tabindex="-1">Query syntax constraints <a class="header-anchor" href="#query-syntax-constraints" aria-label="Permalink to &quot;Query syntax constraints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constraint</th><th>Detail</th></tr></thead><tbody><tr><td><strong>No regular expressions</strong></td><td>Code search uses exact string and qualifier matching — regex patterns are not supported</td></tr><tr><td><strong>Max boolean operators</strong></td><td>5 <code>AND</code> / <code>OR</code> / <code>NOT</code> per query</td></tr><tr><td><strong><code>NOT</code> operator</strong></td><td>Supported for keyword exclusions (e.g. <code>useFeatureFlag NOT deprecated</code>)</td></tr><tr><td><strong>Qualifier-only queries</strong></td><td>Not allowed — at least one non-qualifier search term is required</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title"><code>NOT</code> vs issue/PR search</p><p>The <code>NOT</code> operator is supported in GitHub Code Search, but its behaviour differs from issue/PR search. For code search, use it to exclude keywords — for example <code>useFeatureFlag NOT deprecated</code>, <code>SECRET NOT filename:test</code>.</p></div><h2 id="pagination-behaviour" tabindex="-1">Pagination behaviour <a class="header-anchor" href="#pagination-behaviour" aria-label="Permalink to &quot;Pagination behaviour&quot;">​</a></h2><p><code>github-code-search</code> automatically fetches all available pages (up to page 10) using the GitHub Code Search REST API with <code>per_page=100</code>. Results from all pages are aggregated before being shown in the TUI or printed.</p><p>If 1,000 results are returned and the last page is full, there may be additional results that are silently truncated by GitHub. Refine your query to avoid hitting the ceiling.</p><h2 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to &quot;Official documentation&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/rest/search/search#search-code" target="_blank" rel="noreferrer">GitHub REST API — Search code</a></li><li><a href="https://docs.github.com/en/search-github/searching-on-github/searching-code" target="_blank" rel="noreferrer">Searching code on GitHub</a></li><li><a href="https://docs.github.com/en/search-github/github-code-search/understanding-github-code-search-syntax" target="_blank" rel="noreferrer">Understanding GitHub code search syntax</a></li></ul>',17)])])}const y=t(o,[["render",s]]);export{f as __pageData,y as default};
